1	// Package relayproof implements cross-chain message verification.
2	package relayproof
3	
4	import (
5		"encoding/binary"
6		"sort"
7		"strconv"
8	)
9	
10	// Header is a light-client header at a known height.
11	type Header struct {
12		Chain   string
13		Height  int64
14		Root    string
15		Trusted bool
16	}
17	
18	// Message is one outbound cross-chain message awaiting delivery.
19	type Message struct {
20		ID      string
21		From    string
22		To      string
23		Nonce   uint64
24		Payload string
25		ProofAt int64
26	}
27	
28	// Delivery is the outcome of a relay attempt.
29	type Delivery struct {
30		Message string
31		Status  string
32		Reason  string
33	}
34	
