1	package relayproof
2	
3	import (
4		"bytes"
5		"encoding/binary"
6		"encoding/json"
7		"fmt"
8		"hash/crc32"
9		"io"
10		"os"
11		"path/filepath"
12		"sort"
13		"strconv"
14	)
15	
16	// On-disk format (queue.log):
17	//
18	//	magic   = "RELAYPROOF-QUEUE-V1\n"
19	//	frame   = uint32-be payload length(N) | N bytes JSON payload | uint32-be CRC32-IEEE(payload)
20	//
21	// The log is an append-only write-ahead log. Every mutating operation is
22	// persisted as one framed, checksummed record and fsynced before it is
23	// acknowledged; a success record frames the local success entry and the nonce
24	// consumption together, so the two can never take effect separately.
25	//
26	// A success (result or compacted state) names the consumed triple in three
27	// independent fields, consumeFrom/consumeTo/consumeNonce, alongside consumeBy.
28	// Chain names are stored verbatim as raw UTF-8 — they may contain ':' or even
29	// U+0000 — so the triple is never flattened into one delimiter-joined string,
30	// which would let distinct routing paths share one consumption identity.
31	//
32	// Crash recovery: a frame missing bytes at end of file, or a final frame with
33	// a bad checksum, is the torn tail of a write that was never acknowledged and
34	// is truncated. That recovery is only available once the log's leading
35	// version record has itself been read whole and verified: the magic alone
36	// never establishes a usable version, so a log whose very first record is
37	// partial (only some length bytes, or the length without the body and CRC),
38	// complete but checksum-bad, not a version record, or names an unsupported
39	// version is rejected wholesale with ErrCorrupt and left byte-for-byte
40	// untouched — it can never be truncated down to an empty-looking log that a
41	// later append would turn into a headerless one. Bad checksums or framing
42	// anywhere before the end, a foreign header, or an unsupported version
43	// likewise reject the directory with ErrCorrupt; state is never silently
44	// cleared.
45	//
46	// Logs written by older builds recorded the consumption as one NUL-joined
47	// consumeKey string. Such success entries are still accepted on replay: the
48	// key is validated against the record's own (from,to,nonce) and consumeBy,
49	// and only the record's own triple is marked consumed. A legacy key that does
50	// not match the record it is attached to — a genuinely inconsistent old
51	// record — rejects the whole directory with ErrCorrupt instead of silently
52	// accepting or "repairing" the bad entry.
53	
54	const (
55		logName          = "queue.log"
56		logMagic         = "RELAYPROOF-QUEUE-V1\n"
57		compactThreshold = 4 << 20 // compact when the active log grows past 4 MiB
58		compactFileMode  = 0o600
59		frameHeaderSize  = 4
60		frameCRCsSize    = 4
61	)
62	
63	var crcTable = crc32.MakeTable(crc32.IEEE)
64	
65	// JSON log entry kinds.
66	const (
67		kindVersion = "version"
68		kindSource  = "source"
69		kindHeader  = "header"
70		kindSubmit  = "submit"
71		kindResult  = "result"
72		kindState   = "state" // compacted snapshot: full status after >=1 attempts
73		kindAdvance = "advance"
74		currentLogV = 1
75	)
76	
77	type logEntry struct {
78		T string `json:"t"`
79		V int    `json:"v,omitempty"`
80	
81		Chain   string `json:"chain,omitempty"`
82		Height  int64  `json:"height,omitempty"`
83		Root    string `json:"root,omitempty"`
84		Trusted bool   `json:"trusted,omitempty"`
85	
86		Seq       int64  `json:"seq,omitempty"`
87		ID        string `json:"id,omitempty"`
88		From      string `json:"from,omitempty"`
89		To        string `json:"to,omitempty"`
90		Nonce     uint64 `json:"nonce,omitempty"`
91		Payload   string `json:"payload,omitempty"`
92		ProofAt   int64  `json:"proofAt,omitempty"`
93		ExpiresAt int64  `json:"expiresAt,omitempty"`
94	
95		Now       int64  `json:"now,omitempty"`
96		Status    string `json:"status,omitempty"`
97		Reason    string `json:"reason,omitempty"`
98		Attempts  int    `json:"attempts,omitempty"`
99		NextRetry int64  `json:"nextRetry,omitempty"`
100	
101		// Consumed triple of a success entry, stored as three independent values
102		// so routing paths that share a flattened key stay distinct. consumeBy is
103		// the id of the successful message.
104		ConsumeFrom  string `json:"consumeFrom,omitempty"`
105		ConsumeTo    string `json:"consumeTo,omitempty"`
106		ConsumeNonce uint64 `json:"consumeNonce,omitempty"`
107		ConsumeBy    string `json:"consumeBy,omitempty"`
108	
109		// ConsumeKey is the legacy (pre-triple) NUL-joined consumption string. It
110		// is accepted only while replaying logs written by older builds and is
111		// never written anymore.
112		ConsumeKey string `json:"consumeKey,omitempty"`
113	}
114	
115	// legacyNonceKey reproduces the consumption string used by older builds:
116	// from NUL to NUL nonce. It exists solely to validate records in pre-existing
117	// state directories; new state always uses consumeToken triples.
118	func legacyNonceKey(from, to string, nonce uint64) string {
119		return from + "\x00" + to + "\x00" + strconv.FormatUint(nonce, 10)
120	}
121	
122	type store struct {
123		dir  string
124		f    *os.File
125		size int64
126		// snap, when set, supplies a live-state snapshot for log compaction.
127		snap func() *loadedState
128		// injectErr is a test hook forcing append to fail after opening the file.
129		injectErr error
130	}
131	
132	// loadedState is the fully replayed (or live) queue state.
133	type loadedState struct {
134		sources  map[string]bool
135		headers  map[string]*headerState
136		records  map[string]*Record
137		consumed map[consumeToken]string
138		nextSeq  int64
139		now      int64
140	}
141	
142	func openStore(dir string) (*store, *loadedState, error) {
143		path := filepath.Join(dir, logName)
144	
145		if _, err := os.Stat(path); err != nil {
146			if !os.IsNotExist(err) {
147				return nil, nil, fmt.Errorf("stat %s: %w", logName, err)
148			}
149			if err := createLog(path, dir); err != nil {
150				return nil, nil, err
151			}
152		} else if err := checkMagic(path); err != nil {
153			return nil, nil, err
154		}
155	
156		raw, err := os.ReadFile(path)
157		if err != nil {
158			return nil, nil, fmt.Errorf("read %s: %w", logName, err)
159		}
160		goodLen, state, err := replayLog(raw)
161		if err != nil {
162			return nil, nil, err
163		}
164		if int64(len(raw)) != goodLen {
165			// Drop the torn tail of an entry that can never have been acknowledged.
166			tf, err := os.OpenFile(path, os.O_RDWR, compactFileMode)
167			if err != nil {
168				return nil, nil, fmt.Errorf("open %s for repair: %w", logName, err)
169			}
170			if err := tf.Truncate(goodLen); err != nil {
171				tf.Close()
172				return nil, nil, fmt.Errorf("truncate torn log tail: %w", err)
173			}
174			if err := tf.Sync(); err != nil {
175				tf.Close()
176				return nil, nil, fmt.Errorf("sync repaired %s: %w", logName, err)
177			}
178			if err := tf.Close(); err != nil {
179				return nil, nil, err
180			}
181			if err := syncDir(dir); err != nil {
182				return nil, nil, err
183			}
184		}
185	
186		f, err := os.OpenFile(path, os.O_RDWR|os.O_APPEND, compactFileMode)
187		if err != nil {
188			return nil, nil, fmt.Errorf("open %s for append: %w", logName, err)
189		}
190		if _, err := f.Seek(0, io.SeekEnd); err != nil {
191			f.Close()
192			return nil, nil, err
193		}
194		return &store{dir: dir, f: f, size: goodLen}, state, nil
195	}
196	
197	func createLog(path, dir string) error {
198		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, compactFileMode)
199		if err != nil {
200			return fmt.Errorf("create %s: %w", logName, err)
201		}
202		frame := encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))
203		if _, err := f.Write(append([]byte(logMagic), frame...)); err != nil {
204			f.Close()
205			return fmt.Errorf("write %s header: %w", logName, err)
206		}
207		if err := f.Sync(); err != nil {
208			f.Close()
209			return fmt.Errorf("sync %s: %w", logName, err)
210		}
211		if err := f.Close(); err != nil {
212			return err
213		}
214		return syncDir(dir)
215	}
216	
217	func mustMarshal(e *logEntry) []byte {
218		b, err := json.Marshal(e)
219		if err != nil {
220			panic(err)
221		}
222		return b
223	}
224	
225	// encodeFrame wraps a payload with its big-endian length and CRC32.
226	func encodeFrame(payload []byte) []byte {
227		frame := make([]byte, 0, frameHeaderSize+len(payload)+frameCRCsSize)
228		var hdr [4]byte
229		binary.BigEndian.PutUint32(hdr[:], uint32(len(payload)))
230		frame = append(frame, hdr[:]...)
231		frame = append(frame, payload...)
232		var crc [4]byte
233		binary.BigEndian.PutUint32(crc[:], crc32.Checksum(payload, crcTable))
234		frame = append(frame, crc[:]...)
235		return frame
236	}
237	
238	func checkMagic(path string) error {
239		f, err := os.Open(path)
240		if err != nil {
241			return fmt.Errorf("open %s: %w", logName, err)
242		}
243		defer f.Close()
244		buf := make([]byte, len(logMagic))
245		n, err := io.ReadFull(f, buf)
246		if err != nil && err != io.ErrUnexpectedEOF && err != io.EOF {
247			return fmt.Errorf("read %s header: %w", logName, err)
248		}
249		if n < len(logMagic) || !bytes.Equal(buf, []byte(logMagic)) {
250			return fmt.Errorf("%w: missing or foreign %s header", ErrCorrupt, logName)
251		}
252		return nil
253	}
254	
255	// replayLog parses and validates the log, returning the byte length of the
256	// longest intact prefix and the reconstructed state.
257	func replayLog(raw []byte) (int64, *loadedState, error) {
258		if !bytes.HasPrefix(raw, []byte(logMagic)) {
259			return 0, nil, fmt.Errorf("%w: missing %s header", ErrCorrupt, logMagic)
260		}
261		state := &loadedState{
262			sources:  map[string]bool{},
263			headers:  map[string]*headerState{},
264			records:  map[string]*Record{},
265			consumed: map[consumeToken]string{},
266		}
267	
268		// The leading version record is the precondition for every later recovery
269		// decision: nothing after the magic can be replayed or treated as a
270		// truncatable tail until it has been read complete, checksummed and
271		// confirmed to be a supported version. Validate it on its own so a torn or
272		// bad first record can never look like an empty log that is safe to append
273		// to.
274		verEnd, err := readVersionRecord(raw, len(logMagic))
275		if err != nil {
276			return 0, nil, err
277		}
278		pos := verEnd
279	
280		for pos < len(raw) {
281			// Need at least the length header.
282			if len(raw)-pos < frameHeaderSize {
283				return int64(pos), state, nil // torn length header of an unacked write
284			}
285			n := int(binary.BigEndian.Uint32(raw[pos : pos+frameHeaderSize]))
286			if n == 0 {
287				return 0, nil, fmt.Errorf("%w: zero-length record at offset %d", ErrCorrupt, pos)
288			}
289			bodyStart := pos + frameHeaderSize
290			frameEnd := bodyStart + n + frameCRCsSize
291			if frameEnd > len(raw) {
292				return int64(pos), state, nil // torn body/CRC of an unacked write
293			}
294			payload := raw[bodyStart : bodyStart+n]
295			wantCRC := binary.BigEndian.Uint32(raw[bodyStart+n : frameEnd])
296			if crc32.Checksum(payload, crcTable) != wantCRC {
297				if frameEnd == len(raw) {
298					// Torn sectors of the final, unacknowledged frame.
299					return int64(pos), state, nil
300				}
301				return 0, nil, fmt.Errorf("%w: checksum mismatch at offset %d", ErrCorrupt, pos)
302			}
303			var e logEntry
304			if err := json.Unmarshal(payload, &e); err != nil {
305				return 0, nil, fmt.Errorf("%w: invalid record at offset %d: %v", ErrCorrupt, pos, err)
306			}
307			if e.T == kindVersion {
308				return 0, nil, fmt.Errorf("%w: unexpected version record at offset %d", ErrCorrupt, pos)
309			}
310			if err := applyEntry(state, &e); err != nil {
311				return 0, nil, err
312			}
313			pos = frameEnd
314		}
315		return int64(pos), state, nil
316	}
317	
318	// readVersionRecord reads and validates the log's first record at offset
319	// start, returning the offset just past it. A correct magic prefix alone is
320	// not a valid log: the version record must be fully present, its checksum
321	// must match, and it must name a supported version. Every other shape — a
322	// record cut short at end of file (one to three length bytes, or the length
323	// without the body and CRC), a complete final record with a bad checksum,
324	// invalid JSON, a non-version record, or an unsupported version — is a
325	// corrupt log, never a truncatable tail.
326	func readVersionRecord(raw []byte, start int) (int, error) {
327		if len(raw)-start < frameHeaderSize {
328			return 0, fmt.Errorf("%w: incomplete version record: only %d of %d length bytes after header",
329				ErrCorrupt, len(raw)-start, frameHeaderSize)
330		}
331		n := int(binary.BigEndian.Uint32(raw[start : start+frameHeaderSize]))
332		if n == 0 {
333			return 0, fmt.Errorf("%w: zero-length version record at offset %d", ErrCorrupt, start)
334		}
335		bodyStart := start + frameHeaderSize
336		frameEnd := bodyStart + n + frameCRCsSize
337		if frameEnd > len(raw) {
338			return 0, fmt.Errorf("%w: incomplete version record: length %d but only %d body/checksum bytes present",
339				ErrCorrupt, n, len(raw)-bodyStart)
340		}
341		payload := raw[bodyStart : bodyStart+n]
342		wantCRC := binary.BigEndian.Uint32(raw[bodyStart+n : frameEnd])
343		if crc32.Checksum(payload, crcTable) != wantCRC {
344			return 0, fmt.Errorf("%w: checksum mismatch in version record at offset %d", ErrCorrupt, start)
345		}
346		var e logEntry
347		if err := json.Unmarshal(payload, &e); err != nil {
348			return 0, fmt.Errorf("%w: invalid version record at offset %d: %v", ErrCorrupt, start, err)
349		}
350		if e.T != kindVersion {
351			return 0, fmt.Errorf("%w: first record is %q, not a version record", ErrCorrupt, e.T)
352		}
353		if e.V != currentLogV {
354			return 0, fmt.Errorf("%w: unsupported log version %d", ErrCorrupt, e.V)
355		}
356		return frameEnd, nil
357	}
358	
359	// entryCarriesConsumption reports whether a non-success entry smuggles any
360	// consumption field, which is always corrupt.
361	func entryCarriesConsumption(e *logEntry) bool {
362		return e.ConsumeFrom != "" || e.ConsumeTo != "" || e.ConsumeNonce != 0 ||
363			e.ConsumeKey != "" || e.ConsumeBy != ""
364	}
365	
366	// acceptConsumption validates the triple consumed by a success result or
367	// compacted state entry and records it in s.consumed. The triple must
368	// identify the record's own message and be consumed by that message.
369	//
370	// Logs written by older builds carry the consumption as one NUL-joined
371	// consumeKey. Such an entry is accepted only when that legacy key matches the
372	// record's own triple; it is the record's own triple that is marked consumed,
373	// never the ambiguous flattened string — so two distinct paths that happened
374	// to share one old flattened key each consume only themselves. A legacy key
375	// that does not match its record is an inconsistent record and rejected.
376	func acceptConsumption(s *loadedState, rec *Record, e *logEntry, corrupt func(string, ...any) error) (consumeToken, error) {
377		m := rec.Msg.Message
378		if e.ConsumeBy != e.ID {
379			return consumeToken{}, corrupt("success entry for %q is marked consumed by %q", e.ID, e.ConsumeBy)
380		}
381		token := newConsumeToken(m.From, m.To, m.Nonce)
382		hasTriple := e.ConsumeFrom != "" || e.ConsumeTo != "" || e.ConsumeNonce != 0
383		switch {
384		case hasTriple:
385			if e.ConsumeKey != "" {
386				return consumeToken{}, corrupt("success entry for %q carries both a triple and a legacy consume key", e.ID)
387			}
388			if e.ConsumeFrom != m.From || e.ConsumeTo != m.To || e.ConsumeNonce != m.Nonce {
389				return consumeToken{}, corrupt("success entry for %q carries mismatched nonce consumption: %q -> %q nonce %d", e.ID, e.ConsumeFrom, e.ConsumeTo, e.ConsumeNonce)
390			}
391		case e.ConsumeKey != "":
392			if want := legacyNonceKey(m.From, m.To, m.Nonce); e.ConsumeKey != want {
393				return consumeToken{}, corrupt("success entry for %q carries a legacy consume key for a different path", e.ID)
394			}
395		default:
396			return consumeToken{}, corrupt("success entry for %q carries no nonce consumption", e.ID)
397		}
398		if winner, taken := s.consumed[token]; taken {
399			return consumeToken{}, corrupt("nonce %s already consumed by %q while accepting %q", token, winner, e.ID)
400		}
401		s.consumed[token] = e.ID
402		return token, nil
403	}
404	
405	func applyEntry(s *loadedState, e *logEntry) error {
406		corrupt := func(msg string, args ...any) error {
407			return fmt.Errorf("%w: %s", ErrCorrupt, fmt.Sprintf(msg, args...))
408		}
409		switch e.T {
410		case kindSource:
411			if e.Chain == "" {
412				return corrupt("source entry with empty chain")
413			}
414			s.sources[e.Chain] = true
415		case kindHeader:
416			if e.Chain == "" || e.Height < 0 {
417				return corrupt("bad header entry: %+v", e)
418			}
419			// Replay is permissive: historical same-height coverage is never
420			// rejected as a conflict, and recovery relies only on the header
421			// records actually kept in the log. The latest header is the last one
422			// written; the highest trusted header is the max-height trusted one,
423			// with ties going to the later write (matching old overwrite
424			// semantics). Neither is fabricated from lost history.
425			hs := s.headers[e.Chain]
426			if hs == nil {
427				hs = &headerState{}
428				s.headers[e.Chain] = hs
429			}
430			hs.latest = Header{Chain: e.Chain, Height: e.Height, Root: e.Root, Trusted: e.Trusted}
431			if e.Trusted && (hs.trusted == nil || e.Height >= hs.trusted.Height) {
432				t := hs.latest
433				hs.trusted = &t
434			}
435		case kindSubmit:
436			if e.ID == "" || e.From == "" || e.To == "" || e.ProofAt < 0 || e.ExpiresAt < 0 {
437				return corrupt("bad submit entry: %+v", e)
438			}
439			if _, dup := s.records[e.ID]; dup {
440				return corrupt("duplicate submit for id %q", e.ID)
441			}
442			if e.Seq != s.nextSeq {
443				return corrupt("submit seq %d out of order, expected %d", e.Seq, s.nextSeq)
444			}
445			s.records[e.ID] = &Record{
446				Msg: Envelope{
447					Message: Message{
448						ID:      e.ID,
449						From:    e.From,
450						To:      e.To,
451						Nonce:   e.Nonce,
452						Payload: e.Payload,
453						ProofAt: e.ProofAt,
454					},
455					ExpiresAt: e.ExpiresAt,
456				},
457				Status: StatusPending,
458				Reason: "awaiting first processing",
459				Seq:    e.Seq,
460			}
461			s.nextSeq++
462		case kindResult:
463			rec, ok := s.records[e.ID]
464			if !ok {
465				return corrupt("result for unknown id %q", e.ID)
466			}
467			if isTerminal(rec.Status) {
468				return corrupt("result for terminal id %q", e.ID)
469			}
470			if rec.Attempts > 0 && e.Now < rec.LastProcAt {
471				return corrupt("result time %d before prior time %d for %q", e.Now, rec.LastProcAt, e.ID)
472			}
473			if e.Attempts != rec.Attempts+1 {
474				return corrupt("attempts jump %d -> %d for %q", rec.Attempts, e.Attempts, e.ID)
475			}
476			if !validStatus(e.Status) || e.Status == StatusPending {
477				return corrupt("bad result status %q for %q", e.Status, e.ID)
478			}
479			switch e.Status {
480			case StatusWaiting:
481				if e.NextRetry != e.Now+nextRetryDelay(e.Attempts) {
482					return corrupt("waiting result has wrong retry schedule for %q", e.ID)
483				}
484				if entryCarriesConsumption(e) {
485					return corrupt("waiting result for %q carries nonce consumption fields", e.ID)
486				}
487			case StatusSuccess:
488				if e.NextRetry != 0 {
489					return corrupt("success entry for %q carries retry time", e.ID)
490				}
491				if _, err := acceptConsumption(s, rec, e, corrupt); err != nil {
492					return err
493				}
494			default: // terminal failure kinds
495				if e.NextRetry != 0 || entryCarriesConsumption(e) {
496					return corrupt("terminal entry for %q carries scheduling/consume fields", e.ID)
497				}
498			}
499			rec.Attempts = e.Attempts
500			rec.LastProcAt = e.Now
501			rec.Status = e.Status
502			rec.Reason = e.Reason
503			rec.NextRetry = e.NextRetry
504			if e.Now > s.now {
505				s.now = e.Now
506			}
507		case kindState:
508			// Compacted snapshot: the message already has >=1 attempts and the
509			// entry carries its full current status, so there is no attempts-jump
510			// invariant to check against prior result entries (there are none).
511			rec, ok := s.records[e.ID]
512			if !ok {
513				return corrupt("state for unknown id %q", e.ID)
514			}
515			if rec.Attempts != 0 {
516				return corrupt("duplicate state for id %q", e.ID)
517			}
518			if !validStatus(e.Status) || e.Status == StatusPending {
519				return corrupt("bad state status %q for %q", e.Status, e.ID)
520			}
521			if e.Attempts < 1 {
522				return corrupt("state with zero attempts for %q", e.ID)
523			}
524			switch e.Status {
525			case StatusWaiting:
526				if e.NextRetry != e.Now+nextRetryDelay(e.Attempts) {
527					return corrupt("state has wrong retry schedule for %q", e.ID)
528				}
529				if entryCarriesConsumption(e) {
530					return corrupt("waiting state for %q carries nonce consumption fields", e.ID)
531				}
532			case StatusSuccess:
533				if e.NextRetry != 0 {
534					return corrupt("success state for %q carries retry time", e.ID)
535				}
536				if _, err := acceptConsumption(s, rec, e, corrupt); err != nil {
537					return err
538				}
539			default:
540				if e.NextRetry != 0 || entryCarriesConsumption(e) {
541					return corrupt("terminal state for %q carries scheduling/consume fields", e.ID)
542				}
543			}
544			rec.Attempts = e.Attempts
545			rec.LastProcAt = e.Now
546			rec.Status = e.Status
547			rec.Reason = e.Reason
548			rec.NextRetry = e.NextRetry
549			if e.Now > s.now {
550				s.now = e.Now
551			}
552		case kindAdvance:
553			if e.Now < s.now {
554				return corrupt("advance checkpoint %d before known time %d", e.Now, s.now)
555			}
556			s.now = e.Now
557		default:
558			return corrupt("unknown record type %q", e.T)
559		}
560		return nil
561	}
562	
563	func validStatus(s string) bool {
564		switch s {
565		case StatusPending, StatusWaiting, StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
566			return true
567		}
568		return false
569	}
570	
571	func (s *store) close() error {
572		if s.f == nil {
573			return nil
574		}
575		err := s.f.Sync()
576		cerr := s.f.Close()
577		s.f = nil
578		if err != nil {
579			return err
580		}
581		return cerr
582	}
583	
584	// forceClose releases the file without the final sync after a failed write.
585	func (s *store) forceClose() {
586		if s.f == nil {
587			return
588		}
589		s.f.Close()
590		s.f = nil
591	}
592	
593	// append writes one framed, checksummed, fsynced record.
594	func (s *store) append(e *logEntry) error {
595		if s.injectErr != nil {
596			return s.injectErr
597		}
598		body, err := json.Marshal(e)
599		if err != nil {
600			return fmt.Errorf("encode log entry: %w", err)
601		}
602		if _, err := s.f.Write(encodeFrame(body)); err != nil {
603			return fmt.Errorf("write %s: %w", logName, err)
604		}
605		if err := s.f.Sync(); err != nil {
606			return fmt.Errorf("sync %s: %w", logName, err)
607		}
608		if info, err := s.f.Stat(); err == nil {
609			s.size = info.Size()
610		} else {
611			s.size += int64(frameHeaderSize + len(body) + frameCRCsSize)
612		}
613		return nil
614	}
615	
616	// needsCompaction reports whether the log crossed the compaction threshold.
617	func (s *store) needsCompaction() bool {
618		return s.size > compactThreshold && s.snap != nil
619	}
620	
621	func (s *store) appendRegisterSource(chain string) error {
622		return s.append(&logEntry{T: kindSource, Chain: chain})
623	}
624	
625	func (s *store) appendHeader(h Header) error {
626		return s.append(&logEntry{T: kindHeader, Chain: h.Chain, Height: h.Height, Root: h.Root, Trusted: h.Trusted})
627	}
628	
629	func (s *store) appendSubmit(rec *Record) error {
630		m := rec.Msg.Message
631		return s.append(&logEntry{
632			T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
633			Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
634		})
635	}
636	
637	// appendResult records one processing outcome. On success the consumed triple
638	// (consumeFrom/consumeTo/consumeNonce) and its consumer are part of the same
639	// durable record, committing together atomically. token is nil for every
640	// non-success status.
641	func (s *store) appendResult(now int64, rec *Record, status, reason string, attempts int, token *consumeToken, consumeBy string) error {
642		e := &logEntry{
643			T: kindResult, Now: now, ID: rec.Msg.Message.ID,
644			Status: status, Reason: reason, Attempts: attempts,
645		}
646		if status == StatusWaiting {
647			e.NextRetry = now + nextRetryDelay(attempts)
648		}
649		if status == StatusSuccess {
650			if token == nil || consumeBy == "" {
651				return fmt.Errorf("internal error: success result for %q missing nonce consumption", rec.Msg.Message.ID)
652			}
653			e.ConsumeFrom = token.from
654			e.ConsumeTo = token.to
655			e.ConsumeNonce = token.nonce
656			e.ConsumeBy = consumeBy
657		}
658		return s.append(e)
659	}
660	
661	func (s *store) appendAdvance(now int64) error {
662		return s.append(&logEntry{T: kindAdvance, Now: now})
663	}
664	
665	// compact atomically replaces the log with a deterministic snapshot of live
666	// state. It must run while Queue.mu is held (no concurrent mutation), and only
667	// after in-memory state reflects every acknowledged append.
668	func (s *store) compact(state *loadedState) error {
669		entries := []*logEntry{{T: kindVersion, V: currentLogV}}
670	
671		chains := make([]string, 0, len(state.sources))
672		for c := range state.sources {
673			chains = append(chains, c)
674		}
675		sort.Strings(chains)
676		for _, c := range chains {
677			entries = append(entries, &logEntry{T: kindSource, Chain: c})
678		}
679	
680		headerChains := make([]string, 0, len(state.headers))
681		for c := range state.headers {
682			headerChains = append(headerChains, c)
683		}
684		sort.Strings(headerChains)
685		for _, c := range headerChains {
686			hs := state.headers[c]
687			// Write the highest trusted header first, then the latest header when
688			// it differs. Replay reconstructs latest as the last entry and the
689			// highest trusted as the max-height trusted entry, so this order
690			// restores both exactly.
691			if hs.trusted != nil {
692				entries = append(entries, &logEntry{T: kindHeader, Chain: hs.trusted.Chain, Height: hs.trusted.Height, Root: hs.trusted.Root, Trusted: hs.trusted.Trusted})
693			}
694			if hs.trusted == nil || hs.latest != *hs.trusted {
695				entries = append(entries, &logEntry{T: kindHeader, Chain: hs.latest.Chain, Height: hs.latest.Height, Root: hs.latest.Root, Trusted: hs.latest.Trusted})
696			}
697		}
698	
699		seqs := make([]int64, 0, len(state.records))
700		bySeq := make(map[int64]*Record, len(state.records))
701		for _, rec := range state.records {
702			seqs = append(seqs, rec.Seq)
703			bySeq[rec.Seq] = rec
704		}
705		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
706		for _, seq := range seqs {
707			rec := bySeq[seq]
708			m := rec.Msg.Message
709			entries = append(entries, &logEntry{
710				T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
711				Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
712			})
713			if rec.Attempts > 0 {
714				re := &logEntry{
715					T: kindState, Now: rec.LastProcAt, ID: m.ID,
716					Status: rec.Status, Reason: rec.Reason, Attempts: rec.Attempts,
717				}
718				if rec.Status == StatusWaiting {
719					re.NextRetry = rec.NextRetry
720				}
721				if rec.Status == StatusSuccess {
722					re.ConsumeFrom = m.From
723					re.ConsumeTo = m.To
724					re.ConsumeNonce = m.Nonce
725					re.ConsumeBy = m.ID
726				}
727				entries = append(entries, re)
728			}
729		}
730		if state.now > 0 {
731			entries = append(entries, &logEntry{T: kindAdvance, Now: state.now})
732		}
733	
734		tmp := filepath.Join(s.dir, logName+".compact")
735		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, compactFileMode)
736		if err != nil {
737			return err
738		}
739		abort := func(err error) error {
740			f.Close()
741			os.Remove(tmp)
742			return err
743		}
744		if _, err := f.WriteString(logMagic); err != nil {
745			return abort(err)
746		}
747		for _, e := range entries {
748			body, err := json.Marshal(e)
749			if err != nil {
750				return abort(err)
751			}
752			if _, err := f.Write(encodeFrame(body)); err != nil {
753				return abort(err)
754			}
755		}
756		if err := f.Sync(); err != nil {
757			return abort(err)
758		}
759		if err := f.Close(); err != nil {
760			os.Remove(tmp)
761			return err
762		}
763		if err := os.Rename(tmp, filepath.Join(s.dir, logName)); err != nil {
764			os.Remove(tmp)
765			return err
766		}
767		if err := syncDir(s.dir); err != nil {
768			return err
769		}
770		nf, err := os.OpenFile(filepath.Join(s.dir, logName), os.O_RDWR|os.O_APPEND, compactFileMode)
771		if err != nil {
772			return err
773		}
774		if _, err := nf.Seek(0, io.SeekEnd); err != nil {
775			nf.Close()
776			return err
777		}
778		s.f.Close()
779		s.f = nf
780		if info, err := nf.Stat(); err == nil {
781			s.size = info.Size()
782		}
783		return nil
784	}
785	
786	// syncDir fsyncs a directory so that file creation and rename survive a crash.
787	func syncDir(dir string) error {
788		d, err := os.Open(dir)
789		if err != nil {
790			return fmt.Errorf("open directory for sync: %w", err)
791		}
792		defer d.Close()
793		if err := d.Sync(); err != nil {
794			return fmt.Errorf("sync directory %s: %w", dir, err)
795		}
796		return nil
797	}
