1	package relayproof
2	
3	import (
4		"strings"
5		"testing"
6	)
7	
8	// Regression tests for the retry/expiry boundary of the durable queue: a
9	// message that first waits for trusted-header coverage and is later resolved
10	// by a retry whose scheduled instant sits within one millisecond of its
11	// absolute expiry. All observations go through the public surface — Advance
12	// reports and Query — with caller-supplied Unix-millisecond times.
13	//
14	// Both scenarios share the same original message: id m1, chain a -> b,
15	// nonce 7, proof height 100, absolute expiry 5000. What differs is the first
16	// advance time, which places the scheduled retry one millisecond before the
17	// expiry (success) or exactly on it (expired).
18	const (
19		boundaryID      = "m1"
20		boundaryFrom    = "a"
21		boundaryTo      = "b"
22		boundaryNonce   = 7
23		boundaryProofAt = 100
24		boundaryExpiry  = 5000
25	)
26	
27	// resultFor finds the outcome one Advance reported for a message id.
28	func resultFor(rep *AdvanceReport, id string) (Result, bool) {
29		for _, r := range rep.Results {
30			if r.ID == id {
31				return r, true
32			}
33		}
34		return Result{}, false
35	}
36	
37	// setupBoundaryWaiting registers the source with a trusted header just short
38	// of the proof height, submits the boundary message and runs the first
39	// advance. The message must come out waiting with exactly one attempt and its
40	// next retry scheduled one second later (the first backoff interval).
41	func setupBoundaryWaiting(t *testing.T, q *Queue, firstAdvance int64) {
42		t.Helper()
43		if err := q.RegisterSource(boundaryFrom); err != nil {
44			t.Fatal(err)
45		}
46		// Trusted but insufficient: the source is known, coverage is not there yet.
47		if err := q.UpsertHeader(Header{Chain: boundaryFrom, Height: boundaryProofAt - 1, Root: "0x99", Trusted: true}); err != nil {
48			t.Fatal(err)
49		}
50		if _, err := q.Submit(env(boundaryID, boundaryFrom, boundaryTo, boundaryNonce, boundaryProofAt, boundaryExpiry)); err != nil {
51			t.Fatal(err)
52		}
53	
54		rep, err := q.Advance(firstAdvance)
55		if err != nil {
56			t.Fatal(err)
57		}
58		res, ok := resultFor(rep, boundaryID)
59		if !ok || res.Status != StatusWaiting {
60			t.Fatalf("first advance: want one waiting result for %s, got %+v", boundaryID, rep.Results)
61		}
62		r := statusOf(t, q, boundaryID)
63		wantRetry := firstAdvance + 1000
64		if r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != wantRetry {
65			t.Fatalf("first advance: want waiting attempts=1 retry=%d, got %+v", wantRetry, r)
66		}
67		if r.Msg.ExpiresAt != boundaryExpiry {
68			t.Fatalf("expiry must stay %d, got %d", boundaryExpiry, r.Msg.ExpiresAt)
69		}
70		if !strings.Contains(r.Reason, "100") {
71			t.Fatalf("waiting reason should name the uncovered proof height, got %q", r.Reason)
72		}
73	}
74	
75	// coverProofHeightStillWaiting installs a trusted header covering the proof
76	// height and proves that neither the header update itself nor an advance
77	// before the scheduled retry delivers the message: the two conditions
78	// "header sufficient" and "retry due" are independent, and only the retry
79	// decides when the sufficient header takes effect.
80	func coverProofHeightStillWaiting(t *testing.T, q *Queue, retryAt int64) {
81		t.Helper()
82		if err := q.UpsertHeader(Header{Chain: boundaryFrom, Height: boundaryProofAt, Root: "0x100", Trusted: true}); err != nil {
83			t.Fatal(err)
84		}
85		// The header update alone must not deliver, reschedule or add an attempt.
86		r := statusOf(t, q, boundaryID)
87		if r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != retryAt {
88			t.Fatalf("header update must not process the message, got %+v", r)
89		}
90	
91		// Advancing before the retry instant: header already sufficient, but the
92		// message is not due, so nothing may happen to it.
93		rep, err := q.Advance(retryAt - 1)
94		if err != nil {
95			t.Fatal(err)
96		}
97		if res, ok := resultFor(rep, boundaryID); ok {
98			t.Fatalf("advance before retry must not touch the message, got %+v", res)
99		}
100		r = statusOf(t, q, boundaryID)
101		if r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != retryAt {
102			t.Fatalf("pre-retry advance changed the waiting message: %+v", r)
103		}
104	}
105	
106	// assertTerminalUnchanged verifies the terminal state survives a later
107	// advance untouched: no further results, no rescheduled retry.
108	func assertTerminalUnchanged(t *testing.T, q *Queue, id, status string, at int64) {
109		t.Helper()
110		rep, err := q.Advance(at)
111		if err != nil {
112			t.Fatal(err)
113		}
114		if res, ok := resultFor(rep, id); ok {
115			t.Fatalf("terminal message produced a new result: %+v", res)
116		}
117		r := statusOf(t, q, id)
118		if r.Status != status || r.NextRetry != 0 {
119			t.Fatalf("terminal state changed: %+v", r)
120		}
121	}
122	
123	// The scheduled retry falls one millisecond before the absolute expiry: the
124	// retry wins, the message is delivered on its second attempt, and the nonce
125	// combination is consumed — a later message reusing it is replay.
126	func TestRetryOneMillisecondBeforeExpirySucceeds(t *testing.T) {
127		q, _ := openTempQueue(t)
128		defer q.Close()
129	
130		// First advance at 3999: retry scheduled at 4999 = expiry 5000 - 1ms.
131		setupBoundaryWaiting(t, q, 3999)
132		coverProofHeightStillWaiting(t, q, 4999)
133	
134		// The retry instant itself: header sufficient, not yet expired -> success.
135		rep, err := q.Advance(4999)
136		if err != nil {
137			t.Fatal(err)
138		}
139		res, ok := resultFor(rep, boundaryID)
140		if !ok || res.Status != StatusSuccess {
141			t.Fatalf("retry before expiry: want success, got %+v", rep.Results)
142		}
143		r := statusOf(t, q, boundaryID)
144		if r.Status != StatusSuccess || r.Attempts != 2 || r.NextRetry != 0 {
145			t.Fatalf("want success attempts=2 no retry, got %+v", r)
146		}
147		if r.Reason != res.Reason {
148			t.Fatalf("advance reason %q and query reason %q disagree", res.Reason, r.Reason)
149		}
150		if !strings.Contains(r.Reason, "height 100") {
151			t.Fatalf("success reason must cite the trusted height actually used, got %q", r.Reason)
152		}
153		assertTerminalUnchanged(t, q, boundaryID, StatusSuccess, 6000)
154	
155		// The nonce combination was consumed by m1: a new id on the same path is
156		// replay and must name the message that actually succeeded. Its own source
157		// is registered and the trusted header covers its proof height, so only
158		// the consumed nonce can stop it.
159		if _, err := q.Submit(env("m2", boundaryFrom, boundaryTo, boundaryNonce, boundaryProofAt, 0)); err != nil {
160			t.Fatal(err)
161		}
162		rep, err = q.Advance(7000)
163		if err != nil {
164			t.Fatal(err)
165		}
166		res, ok = resultFor(rep, "m2")
167		if !ok || res.Status != StatusReplay {
168			t.Fatalf("same-combination message must be replay, got %+v", rep.Results)
169		}
170		r = statusOf(t, q, "m2")
171		if r.Status != StatusReplay || r.Reason != res.Reason ||
172			!strings.Contains(r.Reason, boundaryID) {
173			t.Fatalf("replay must name the consuming message %s, got %+v", boundaryID, r)
174		}
175	}
176	
177	// The scheduled retry falls exactly on the absolute expiry instant: reaching
178	// the expiry counts as expired even though the trusted header already covers
179	// the proof height, and the nonce combination is left unconsumed — a later
180	// message reusing it succeeds.
181	func TestRetryExactlyAtExpiryInstantExpires(t *testing.T) {
182		q, _ := openTempQueue(t)
183		defer q.Close()
184	
185		// First advance at 4000: retry scheduled at 5000 = expiry exactly.
186		setupBoundaryWaiting(t, q, 4000)
187		coverProofHeightStillWaiting(t, q, 5000)
188	
189		// The retry instant equals the expiry instant: expiry wins over the now
190		// sufficient header.
